function renderSensitivity(m) {
  const product=state.products.find(p=>p.id===state.selectedProduct)||state.products[0]; if(!product){$("#sensitivity-chart").innerHTML="";return;}
  const row=m.productRows.find(p=>p.id===product.id); const span=Math.max(1,row.monthlyPrice*1.75); const min=Math.max(0,row.monthlyPrice-span*.45), max=row.monthlyPrice+span*.55; const n=30; const profits=[];
  for(let i=0;i<=n;i++){const price=min+(max-min)*i/n; const monthlyPrice=price; let varUnit=Number(scenarioValueFor(product,"baseVariableCost"))||0; m.expenseRows.filter(e=>e.kind!=="fixed"&&e.enabled&&(!e.productId||e.productId===product.id)).forEach(e=>{if(e.kind==="perUnit")varUnit+=e.currentAmount*(e.usageKey==="rendersPerCustomer"?row.rendersPerCustomer:Number(e.usagePerUnit||1));if(e.kind==="percentRevenue")varUnit+=monthlyPrice*e.currentAmount;if(e.kind==="perTransaction")varUnit+=e.currentAmount/(product.billing==="annual"?12:1);}); const other=m.productRows.filter(x=>x.id!==product.id).reduce((s,x)=>s+x.totalContribution,0); profits.push(other + (monthlyPrice-varUnit)*row.volume - m.fixedOperatingCosts); }
  const w=610,h=205,l=45,r=12,t=15,b=30,pw=w-l-r,ph=h-t-b; const lo=Math.min(...profits,0),hi=Math.max(...profits,0),range=Math.max(1,hi-lo);const path=profits.map((val,i)=>`${i?"L":"M"}${(l+pw*i/n).toFixed(1)},${(t+ph-(val-lo)/range*ph).toFixed(1)}`).join(" ");const zeroY=t+ph-(0-lo)/range*ph;
  const xLabels=`<text x="${l}" y="${h-6}" fill="#83909e" font-size="9">${money(min)}</text><text x="${l+pw/2}" y="${h-6}" fill="#83909e" font-size="9" text-anchor="middle">Price / active customer-month</text><text x="${l+pw}" y="${h-6}" fill="#83909e" font-size="9" text-anchor="end">${money(max)}</text>`;
  $("#sensitivity-chart").innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><line x1="${l}" y1="${zeroY}" x2="${w-r}" y2="${zeroY}" stroke="#5b6874" stroke-dasharray="4 4"/><text x="${l-7}" y="${t+8}" text-anchor="end" fill="#86929e" font-size="9">${money(hi,0)}</text><text x="${l-7}" y="${h-b}" text-anchor="end" fill="#86929e" font-size="9">${money(lo,0)}</text><path d="${path}" fill="none" stroke="#c4a6ff" stroke-width="2.5"/>${xLabels}</svg>`;
}
