const crcTable=(()=>{const table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}return table;})();
function crc32(bytes){let c=0xffffffff;for(const byte of bytes)c=crcTable[(c^byte)&0xff]^(c>>>8);return (c^0xffffffff)>>>0;}
function u16(view,offset,value){view.setUint16(offset,value,true);} function u32(view,offset,value){view.setUint32(offset,value>>>0,true);}
function zipStored(entries){
  const encoder=new TextEncoder();let localParts=[],centralParts=[],offset=0;
  for(const [name,content] of Object.entries(entries)){const nameBytes=encoder.encode(name),data=encoder.encode(content),crc=crc32(data);const local=new Uint8Array(30+nameBytes.length);const lv=new DataView(local.buffer);u32(lv,0,0x04034b50);u16(lv,4,20);u16(lv,6,0x0800);u16(lv,8,0);u16(lv,10,0);u16(lv,12,0);u32(lv,14,crc);u32(lv,18,data.length);u32(lv,22,data.length);u16(lv,26,nameBytes.length);u16(lv,28,0);local.set(nameBytes,30);localParts.push(local,data);
    const central=new Uint8Array(46+nameBytes.length);const cv=new DataView(central.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x0800);u16(cv,10,0);u16(cv,12,0);u16(cv,14,0);u32(cv,16,crc);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,nameBytes.length);u16(cv,30,0);u16(cv,32,0);u16(cv,34,0);u16(cv,36,0);u32(cv,38,0);u32(cv,42,offset);central.set(nameBytes,46);centralParts.push(central);offset+=local.length+data.length;
  }
  const centralSize=centralParts.reduce((a,b)=>a+b.length,0);const end=new Uint8Array(22);const ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,4,0);u16(ev,6,0);u16(ev,8,Object.keys(entries).length);u16(ev,10,Object.keys(entries).length);u32(ev,12,centralSize);u32(ev,16,offset);u16(ev,20,0);const all=[...localParts,...centralParts,end];const size=all.reduce((a,b)=>a+b.length,0);const zip=new Uint8Array(size);let cursor=0;for(const part of all){zip.set(part,cursor);cursor+=part.length;}return zip;
}
function downloadBlob(blob,filename) { const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function downloadJSON(){if(!state.confirmed||state.confirmed._fingerprint!==fingerprint()){showToast("Confirm a current decision before downloading.");return;}const snapshot=structuredClone(state.confirmed);delete snapshot._fingerprint;downloadBlob(new Blob([JSON.stringify(snapshot,null,2)],{type:"application/json;charset=utf-8"}),"Pricing_Decision_Data.json");}
function downloadDOCX(){if(!state.confirmed||state.confirmed._fingerprint!==fingerprint()){showToast("Confirm a current decision before downloading.");return;}const snapshot=structuredClone(state.confirmed);delete snapshot._fingerprint;const bytes=reportDocument(snapshot);downloadBlob(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"}),"Pricing_Decision_Report.docx");}

function exportBackup(){const backup={format:"swyft-pricing-lab-backup",version:1,exportedAt:new Date().toISOString(),state};downloadBlob(new Blob([JSON.stringify(backup,null,2)],{type:"application/json;charset=utf-8"}),"Swyft_Pricing_Lab_Backup.json");}
async function importBackup(file){try{const parsed=JSON.parse(await file.text());const incoming=parsed.state;if(parsed.format!=="swyft-pricing-lab-backup"||parsed.version!==1||!Array.isArray(incoming?.expenses)||!Array.isArray(incoming?.products))throw new Error("That file is not a Swyft Pricing Lab backup.");state={...freshState(),...incoming,evaluation:null,confirmed:null,confirmationDraft:null};invalidate();renderAll();showToast("Backup imported. Re-evaluate before confirming.");}catch(error){showToast(error.message||"Could not import this backup.");}}

function findExpense(id){return state.expenses.find(item=>item.id===id);}
function findProduct(id){return state.products.find(item=>item.id===id);}
function addCustomExpense(form){const data=new FormData(form);const name=String(data.get("name")||"").trim();if(!name)return;const kind=data.get("classification");const startup=data.get("period")==="oneTime";const value=Number(data.get("amount"))||0;const allocation=String(data.get("allocation")||"business");const item={id:`custom-expense-${state.nextId++}`,name,category:String(data.get("category")||"Other"),description:String(data.get("description")||""),kind,scope:startup?"startup":"operating",period:startup?"oneTime":String(data.get("period")||"monthly"),amount:value,benchmark:null,evidence:String(data.get("evidence")||"Student-Entered"),sourceUrl:String(data.get("sourceUrl")||""),assumptions:String(data.get("assumptions")||""),enabled:true,custom:true,productId:allocation==="business"?null:allocation,min:0,max:Math.max(100,value*2),step:.01};if(kind==="percentRevenue")item.max=.1;if(startup){item.includeAmortization=false;item.amortizeMonths=36;}else item.scenarioAmounts={lean:value,typical:value,expansion:value};state.expenses.push(item);state.evaluation=null;state.confirmed=null;$("#expense-dialog").close();form.reset();renderAll();showToast("Expense added to the current model.");}
function newProduct(data){const id=`student-plan-${state.nextId++}`;const currentPrice=Number(data.get("price"))||0;const billing=String(data.get("billing")||"monthly");const p={id,name:String(data.get("name")||"Student scenario").trim(),description:String(data.get("description")||"").trim(),billing,price:currentPrice,volume:Number(data.get("volume"))||0,baseVariableCost:Number(data.get("variableCost"))||0,rendersPerCustomer:Number(data.get("renders"))||0,features:String(data.get("features")||"").split(",").map(x=>x.trim()).filter(Boolean),addons:String(data.get("addons")||"").split(",").map(x=>x.trim()).filter(Boolean),status:"Student scenario",scenarioValues:{lean:{price:currentPrice,volume:Math.round((Number(data.get("volume"))||0)*.5),rendersPerCustomer:Number(data.get("renders"))||0,baseVariableCost:Number(data.get("variableCost"))||0},typical:{price:currentPrice,volume:Number(data.get("volume"))||0,rendersPerCustomer:Number(data.get("renders"))||0,baseVariableCost:Number(data.get("variableCost"))||0},expansion:{price:currentPrice,volume:Math.round((Number(data.get("volume"))||0)*1.5),rendersPerCustomer:Number(data.get("renders"))||0,baseVariableCost:Number(data.get("variableCost"))||0}}};state.products.push(p);state.selectedProduct=id;}
let editingProductId=null;
function editProduct(product){const form=$("#product-form");const set=(key,value)=>{const el=form.elements.namedItem(key);if(el)el.value=value;};set("name",product.name);set("description",product.description);set("billing",product.billing);set("price",scenarioValueFor(product,"price"));set("volume",scenarioValueFor(product,"volume"));set("variableCost",scenarioValueFor(product,"baseVariableCost"));set("renders",scenarioValueFor(product,"rendersPerCustomer"));set("features",(product.features||[]).join(", "));set("addons",(product.addons||[]).join(", "));$(".modal-head h2",$("#product-dialog")).textContent="Edit product or plan";$("#product-dialog .eyebrow").textContent=product.status||"STUDENT SCENARIO";editingProductId=product.id;$("#product-dialog").showModal();}
function saveEditedProduct(form){const product=findProduct(editingProductId);if(!product)return;const data=new FormData(form);product.name=String(data.get("name")||product.name).trim();product.description=String(data.get("description")||"").trim();product.billing=String(data.get("billing")||"monthly");product.features=String(data.get("features")||"").split(",").map(x=>x.trim()).filter(Boolean);product.addons=String(data.get("addons")||"").split(",").map(x=>x.trim()).filter(Boolean);for(const [field,key] of [["price","price"],["volume","volume"],["variableCost","baseVariableCost"],["renders","rendersPerCustomer"]])setProductValue(product,key,Number(data.get(field))||0);$("#product-dialog").close();editingProductId=null;state.evaluation=null;state.confirmed=null;$(".modal-head h2",$("#product-dialog")).textContent="Add a product or plan";$("#product-dialog .eyebrow").textContent="STUDENT SCENARIO";renderAll();}
function useScenario(id){state.scenario=id;state.evaluation=null;state.confirmed=null;invalidate();renderAll();showToast(`Now exploring ${SCENARIOS[id]?.name||customScenario()?.name||"custom scenario"}.`);}
function saveCustomScenario(){const name=prompt("Name this custom operating scenario:",`Custom case ${state.customScenarios.length+1}`);if(!name||!name.trim())return;const id=`custom-${Date.now()}-${state.nextId++}`;const item={id,name:name.trim().slice(0,45),expenseAmounts:Object.fromEntries(state.expenses.map(exp=>[exp.id,amountFor(exp)])),productValues:Object.fromEntries(state.products.map(p=>[p.id,{price:scenarioValueFor(p,"price"),volume:scenarioValueFor(p,"volume"),rendersPerCustomer:scenarioValueFor(p,"rendersPerCustomer"),baseVariableCost:scenarioValueFor(p,"baseVariableCost")}]))};state.customScenarios.push(item);state.scenario=`custom:${id}`;state.evaluation=null;state.confirmed=null;renderAll();showToast("Custom scenario saved.");}

function bindEvents(){
  document.body.addEventListener("input",event=>{
    const el=event.target;
    if(el.dataset.expense){const expense=findExpense(el.dataset.expense);if(!expense)return;const field=el.dataset.field;if(field==="amount"){let value=Number(el.value);if(expense.kind==="percentRevenue"&&el.type==="number")value/=100;if(!Number.isFinite(value))return;setExpenseValue(expense,value);const card=$(`[data-expense-card="${CSS.escape(expense.id)}"]`);if(card){const range=$(".expense-range",card),numeric=$(".expense-amount",card);if(el!==range)range.value=value;if(el!==numeric)numeric.value=expense.kind==="percentRevenue"?(value*100).toFixed(1):value.toFixed(2);const strong=$(".expense-total strong",card);if(strong)strong.textContent=expense.kind==="percentRevenue"?`${(value*100).toFixed(1)}% of sales`:expense.kind==="perTransaction"?`${money(value)} / transaction`:expense.kind==="perUnit"?`${money(value)} / unit`:expense.scope==="startup"?`${money(value)} once`:`${money(costMonthlyPreview(expense,value))} / mo`;}}
      else if(field==="enabled"){expense.enabled=el.checked;const card=$(`[data-expense-card="${CSS.escape(expense.id)}"]`);card?.classList.toggle("disabled",!expense.enabled);}
      else if(field==="includeAmortization")expense.includeAmortization=el.checked;
      else if(field==="amortizeMonths")expense.amortizeMonths=Math.max(1,Number(el.value)||1);
      else if(field==="scope"){expense.scope=el.value;if(expense.scope==="startup")expense.period="oneTime";else if(expense.period==="oneTime")expense.period="monthly";}
      else if(field==="period"||field==="kind"||field==="evidence"||field==="productId")expense[field]=el.value;
      else expense[field]=el.value;
      invalidate();renderDerived(); return;
    }
    if(el.dataset.product){const product=findProduct(el.dataset.product);if(!product)return;const field=el.dataset.field;const keys={price:"price",volume:"volume",baseVariableCost:"baseVariableCost",rendersPerCustomer:"rendersPerCustomer"};if(keys[field])setProductValue(product,keys[field],Number(el.value)||0);else product[field]=el.value;state.evaluation=null;state.confirmed=null;invalidate();const card=$(`[data-product-card="${CSS.escape(product.id)}"]`);if(card){const name=$(".product-name",card);if(name&&name!==el)name.value=product.name;const price=$(".product-price-row strong",card);if(price)price.textContent=money(scenarioValueFor(product,"price"));const eq=$(".bill-label span",card);if(eq)eq.textContent=`${money(normalizePrice(scenarioValueFor(product,"price"),product.billing))} / active unit-month`;}
      renderDerived();return;
    }
    if(el.id==="justification"){state.confirmationDraft={...(state.confirmationDraft||{}),justification:el.value};persist();}
  });
  document.body.addEventListener("change",event=>{const el=event.target;if(el.dataset.expense||el.dataset.product){renderAll();} });
  $("#scenario-select").addEventListener("change",e=>useScenario(e.target.value));
  $("#chart-range").addEventListener("input",()=>renderBreakEvenChart(model()));
  $("#add-expense").addEventListener("click",()=>{$("#expense-dialog").showModal();});
  $("#expense-form").addEventListener("submit",e=>{e.preventDefault();addCustomExpense(e.currentTarget);});
  $("#add-product").addEventListener("click",()=>{editingProductId=null;$("#product-form").reset();$("#product-form").elements.price.value="4.99";$("#product-form").elements.volume.value="25";$("#product-form").elements.renders.value="10";$(".modal-head h2",$("#product-dialog")).textContent="Add a product or plan";$("#product-dialog").showModal();});
  $("#product-form").addEventListener("submit",e=>{e.preventDefault();if(editingProductId)saveEditedProduct(e.currentTarget);else{newProduct(new FormData(e.currentTarget));e.currentTarget.reset();$("#product-dialog").close();state.evaluation=null;state.confirmed=null;renderAll();showToast("Student scenario added.");}});
  $("#add-product").addEventListener("click",()=>{$("#product-dialog").setAttribute("aria-label","Add student product scenario");});
  $("#add-expense").addEventListener("click",()=>{const select=$("#expense-form [name=allocation]");select.innerHTML='<option value="business">Shared business overhead</option>'+state.products.map(p=>`<option value="${escapeHTML(p.id)}">${escapeHTML(p.name)}</option>`).join("");});
  $("#save-scenario").addEventListener("click",saveCustomScenario);
  $("#reset-costs").addEventListener("click",()=>{if(!confirm("Restore suggested expense values and the starting product scenario? Your current model will be replaced in this browser. Export a backup first if you need to keep it."))return;state=freshState();invalidate();renderAll();showToast("Suggested values restored.");});
  $("#backup-button").addEventListener("click",exportBackup);$("#backup-file").addEventListener("change",e=>{const file=e.target.files?.[0];if(file)importBackup(file);e.target.value="";});
  $("#evaluate-button").addEventListener("click",evaluateDecision);$("#confirm-button").addEventListener("click",openConfirmation);$("#revise-button").addEventListener("click",()=>{$("#confirmation-panel").hidden=true;document.querySelector("#costs").scrollIntoView({behavior:"smooth"});});$("#finalize-button").addEventListener("click",confirmDecision);$("#download-docx").addEventListener("click",downloadDOCX);$("#download-json").addEventListener("click",downloadJSON);
  document.body.addEventListener("click",event=>{const btn=event.target.closest("[data-action]");if(!btn)return;const id=btn.dataset.id;const action=btn.dataset.action;
    if(action==="details"){const detail=$(`[data-details="${CSS.escape(id)}"]`);detail.hidden=!detail.hidden;btn.setAttribute("aria-expanded",String(!detail.hidden));}
    if(action==="delete-expense"){if(confirm("Delete this custom expense from the working model?")){state.expenses=state.expenses.filter(x=>x.id!==id);state.evaluation=null;state.confirmed=null;renderAll();}}
    if(action==="delete-product"){if(confirm("Remove this student-created product or plan?")){state.products=state.products.filter(x=>x.id!==id);state.expenses.forEach(e=>{if(e.productId===id)e.productId=null;});if(state.selectedProduct===id)state.selectedProduct=state.products[0]?.id;state.evaluation=null;state.confirmed=null;renderAll();}}
    if(action==="edit-product"){const product=findProduct(id);if(product)editProduct(product);}
    if(action==="select-product"){state.selectedProduct=id;state.evaluation=null;state.confirmed=null;invalidate();renderProducts();renderDerived();showToast("Competitive comparison now follows this plan.");}
    if(action==="use-scenario")useScenario(id);
  });
  const links=$$(".nav-link");const sections=links.map(link=>$(link.getAttribute("href"))).filter(Boolean);const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){links.forEach(link=>link.classList.toggle("active",link.getAttribute("href")==="#"+entry.target.id));}}),{rootMargin:"-25% 0px -65% 0px"});sections.forEach(section=>observer.observe(section));
}

async function init(){
  try{const response=await fetch(new URL("./data/research.json",import.meta.url));if(!response.ok)throw new Error(`Research data request returned ${response.status}`);research=await response.json();if(!Array.isArray(research.competitors)||!Array.isArray(research.pricing_offers)||research.pricing_offers.length!==28)throw new Error("The bundled Mission 1 data did not pass its record check.");
    state=loadState();if(state.scenario.startsWith("custom:")&&!state.customScenarios.some(item=>`custom:${item.id}`===state.scenario))state.scenario="typical";if(!state.products.some(p=>p.id===state.selectedProduct))state.selectedProduct=state.products[0]?.id;bindEvents();renderAll();
  }catch(error){$(".main").innerHTML=`<section class="section"><div class="eyebrow">LABORATORY COULD NOT START</div><h1>Research data did not load.</h1><p>${escapeHTML(error.message)} Check that the complete site folder is available, then reload.</p></section>`;}
}
init();
